function migrateV23(){state.settings.implementations=state.settings.implementations||{googleClientId:'',googleRedirectUrl:location.origin+location.pathname};state.teamLogo=state.teamLogo||'';state.devices.forEach(d=>{d.uptimeMs??=0;d.ssid??='Huerta-IoT';d.rssi??=-48;d.firmware??='1.0.0';d.mac??='—';d.mqttConnected??=true;d.lastSeen??=new Date().toISOString()});save()}
function fileData(file,max=2*1024*1024){return new Promise((resolve,reject)=>{if(!file)return resolve('');if(file.size>max)return reject(Error('La imagen supera los 2 MB.'));if(!/^image\//.test(file.type))return reject(Error('Seleccioná un archivo de imagen.'));const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('No se pudo leer la imagen.'));reader.readAsDataURL(file)})}
function formatUptime(ms=0){let total=Math.floor(ms/1000),days=Math.floor(total/86400);total%=86400;const hours=Math.floor(total/3600),minutes=Math.floor(total%3600/60);return`${days?days+' d ':''}${hours} h ${minutes} min`}
