async function zoneEditor(previous=''){const result=await Swal.fire({title:previous?'Editar zona':'Nueva zona',input:'text',inputValue:previous,inputLabel:'Nombre de la zona',showCancelButton:true,confirmButtonText:'Guardar',inputValidator:v=>!v.trim()?'Ingresá un nombre':state.zones.some(z=>z.toLowerCase()===v.trim().toLowerCase()&&z!==previous)?'La zona ya existe':undefined});if(!result.isConfirmed)return;const name=result.value.trim();if(previous){state.zones=state.zones.map(z=>z===previous?name:z);state.devices.forEach(d=>{if(d.zone===previous)d.zone=name})}else state.zones.push(name);save();renderHeader();renderZonesManager();if(!state.currentUser?.id?.startsWith('demo-')){const client=supabase();if(previous)await client.from('zones').update({name}).eq('name',previous);else await client.from('zones').insert({name})}toast('Zona guardada')}
